import json, base64, hashlib
from archive.hollin import *
from archive import hollin

class Srv:
    def __init__(s): s.log=[]; s.parts={}; s.n=0; s.drop=False
    def now(s): return 1000.0
    def send(s,m,p,h,b):
        s.log.append((m,p,h,b if not isinstance(b,bytes) else len(b)))
        def R(st,o): return Response(st,{},json.dumps(o).encode())
        if p=='/v3/uploads': return R(201,{'upload_id':'up_1','chunk_size':b['chunk_size'],'expires_at':99999})
        if s.drop: s.drop=False; return R(410,{'error':{'code':'upload_expired'}})
        if m=='PUT':
            n=int(p.rsplit('/',1)[1]); s.n+=1; s.parts[n]=(len(b),h['Part-Checksum'],'"e%d"'%s.n); return R(200,{'part':n,'size':len(b),'etag':s.parts[n][2]})
        if m=='GET': return R(200,{'upload_id':'x','expires_at':1,'parts':[{'part':n,'size':a,'checksum':c,'etag':e} for n,(a,c,e) in sorted(s.parts.items())]})
        return R(201,{'file_id':'fl','name':'n','size':1,'checksum':b['checksum']})
d=b'Hollin example part one, and part two.'
